INSERT INTO trading_cards (card_game, set_name, card_name, card_number, rarity, card_type, hp, attacks, weakness, resistance, retreat_cost, illustrator, print_versions, card_image_url, source_url, created_at, updated_at) VALUES ('Pokemon TCG', 'Paradox RiftPAR', 'Technical Machine: Evolution', '178', 'Common', NULL, NULL, '[{"name": "The Pok\u00e9mon this card is attached to can use the attack on this card. (You still need the necessary Energy to use this attack.) If this card is attached to 1 of your Pok\u00e9mon, discard it at the end of your turn.[C] EvolutionChoose up to 2 of your Benched Pok\u00e9mon. For each of those Pok\u00e9mon, search your deck for a card that evolves from that Pok\u00e9mon and put it onto that Pok\u00e9mon to evolve it. Then, shuffle your deck.", "details": "The Pok\u00e9mon this card is attached to can use the attack on this card. (You still need the necessary Energy to use this attack.) If this card is attached to 1 of your Pok\u00e9mon, discard it at the end of your turn.[C] EvolutionChoose up to 2 of your Benched Pok\u00e9mon. For each of those Pok\u00e9mon, search your deck for a card that evolves from that Pok\u00e9mon and put it onto that Pok\u00e9mon to evolve it. Then, shuffle your deck."}]', NULL, NULL, NULL, NULL, '["Int. Prints USD EUR", "Paradox Rift#178 $0.48 0.22\u20ac", "JP. Prints", "Scarlet & Violet Promotional Cards#146", "Future Flash#63", "Stellar Miracle Deck Build Box#28", "Terastal Fest ex#160", "Battle Partners Deck Build Box#29", "Premium Trainer Box MEGA#33", "Paradox Rift (PAR)#178 \u00b7 Uncommon", "Paradox Rift#178", "$0.48", "0.22\u20ac"]', 'https://limitless3.nyc3.cdn.digitaloceanspaces.com/markets/icons/cardmarket.png', 'https://limitlesstcg.com/cards/PAR/178', '2025-08-07 04:07:36', '2025-08-07 04:07:36');
